import React, { useState, useEffect } from 'react';
import upArrow from '../../img/up-arrow.svg';
import './toTop.css';

export default function ToTop() {
    const [bottomOffset, setBottomOffset] = useState(20);

    const scrollToTop = () =>
        window.scrollTo({ top: 0, behavior: 'smooth' });

    useEffect(() => {
        const footer = document.getElementById('page-footer');
        if (!footer) return;

        const updateOffset = () => {
            const rect = footer.getBoundingClientRect();
            // if footer’s top is inside the viewport...
            if (rect.top < window.innerHeight) {
                // compute how far it intrudes:
                const intrusion = window.innerHeight - rect.top;
                setBottomOffset(intrusion + 20);
            } else {
                setBottomOffset(20);
            }
        };

        // run on scroll and resize
        window.addEventListener('scroll', updateOffset, { passive: true });
        window.addEventListener('resize', updateOffset);
        updateOffset(); // initialise
        return () => {
            window.removeEventListener('scroll', updateOffset);
            window.removeEventListener('resize', updateOffset);
        };
    }, []);

    return (
        <aside
            className="toTop"
            onClick={scrollToTop}
            style={{ bottom: `${bottomOffset}px` }}
        >
            <div className="toTop-container">
                <img src={upArrow} alt="Up arrow" className="toTop-img" />
            </div>
        </aside>
    );
}
